export const x_pileNamePattern = /^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/;
export const x_sessionIdPattern = /^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$/;

const x_reservedNames = new Set([".", ".."]);

export function IsValidPileName(name: string): boolean
{
  if (name.length === 0 || x_reservedNames.has(name))
  {
    return false;
  }

  if (name.includes("/") || name.includes("\\"))
  {
    return false;
  }

  return x_pileNamePattern.test(name);
}

export function IsValidSessionId(sessionId: string): boolean
{
  if (sessionId.length === 0 || x_reservedNames.has(sessionId))
  {
    return false;
  }

  if (sessionId.includes("/") || sessionId.includes("\\"))
  {
    return false;
  }

  return x_sessionIdPattern.test(sessionId);
}

import { randomUUID } from "node:crypto";

export const x_chatEnvelopeVersion = 1;

export interface ChatEnvelope
{
  v: typeof x_chatEnvelopeVersion;
  kind: string;
  id: string;
  pile: string;
  sessionId: string;
  clientId?: string;
  sequence?: number;
  timestamp: string;
  payload?: unknown;
}

export interface CreateChatEnvelopeInput
{
  kind: string;
  pile: string;
  sessionId: string;
  clientId?: string;
  sequence?: number;
  payload?: unknown;
  id?: string;
  timestamp?: string;
}

export function CreateChatEnvelope(input: CreateChatEnvelopeInput): ChatEnvelope
{
  const envelope: ChatEnvelope = {
    v: x_chatEnvelopeVersion,
    kind: input.kind,
    id: input.id ?? randomUUID(),
    pile: input.pile,
    sessionId: input.sessionId,
    timestamp: input.timestamp ?? new Date().toISOString(),
  };

  if (input.clientId !== undefined)
  {
    envelope.clientId = input.clientId;
  }

  if (input.sequence !== undefined)
  {
    envelope.sequence = input.sequence;
  }

  if (input.payload !== undefined)
  {
    envelope.payload = input.payload;
  }

  return envelope;
}

import { existsSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

export interface SheafChatPaths
{
  globalConfigFile: string;
  apiKeysFile: string;
  servicesJsonFile: string;
  dataDir: string;
  sessionsDir: string;
  authDir: string;
}

const x_globalConfigRelative = "config/global_config.json";
const x_apiKeysRelative = "config/api_keys.json";
const x_servicesJsonRelative = "config/services.json";
const x_dataDirRelative = "data/sheaf-chat";
const x_sessionsDirRelative = "data/sheaf-chat/sessions";
const x_authDirRelative = "data/sheaf-chat/auth";

const x_moduleDir =
  typeof __dirname === "string"
    ? __dirname
    : path.dirname(fileURLToPath(import.meta.url));

export function FindRepositoryRoot(startPath?: string): string | undefined
{
  const startDir = path.resolve(startPath ?? process.cwd());
  let current = startDir;

  while (current !== path.dirname(current))
  {
    const servicesJsonPath = path.join(current, "config", "services.json");
    const structureDir = path.join(current, "structure");

    if (existsSync(servicesJsonPath) && existsSync(structureDir))
    {
      return current;
    }

    current = path.dirname(current);
  }

  return undefined;
}

export function ResolveRepositoryPath(relativePath: string, root?: string): string
{
  const repoRoot = root ?? FindRepositoryRoot(x_moduleDir) ?? FindRepositoryRoot();

  if (repoRoot === undefined)
  {
    throw new Error("repository root not found");
  }

  return path.join(repoRoot, relativePath);
}

export function GetDefaultSheafChatPaths(root?: string): SheafChatPaths
{
  const repoRoot = root ?? FindRepositoryRoot(x_moduleDir) ?? FindRepositoryRoot();

  if (repoRoot === undefined)
  {
    throw new Error("repository root not found");
  }

  return {
    globalConfigFile: path.join(repoRoot, x_globalConfigRelative),
    apiKeysFile: path.join(repoRoot, x_apiKeysRelative),
    servicesJsonFile: path.join(repoRoot, x_servicesJsonRelative),
    dataDir: path.join(repoRoot, x_dataDirRelative),
    sessionsDir: path.join(repoRoot, x_sessionsDirRelative),
    authDir: path.join(repoRoot, x_authDirRelative),
  };
}

export {
  x_apiKeysRelative,
  x_authDirRelative,
  x_dataDirRelative,
  x_globalConfigRelative,
  x_servicesJsonRelative,
  x_sessionsDirRelative,
};

